const r = await tools.exec_command({cmd:"cat > "$STAMPED_JUDGE_OUTPUT/access_probe.py" <<'PY'
import concurrent.futures, json, os, urllib.request
sources=json.load(open(os.path.join(os.environ['STAMPED_JUDGE_TARGET'],'input','sources.json')))
urls=[('collection',sources['collection']),('cohort',sources['cohort_source']['url']),('methods',sources['methods_source']['url'])]
urls.extend((name,entry['url']) for name,entry in sources['files'].items())
def check(row):
 name,url=row
 req=urllib.request.Request(url,method='HEAD',headers={'User-Agent':'frozen-independent-assessment/1.0'})
 try:
  with urllib.request.urlopen(req,timeout=20) as r:
   return {'name':name,'host':urllib.request.urlparse(url).hostname if hasattr(urllib.request,'urlparse') else url.split('/')[2],'status':r.status,'content_length':r.headers.get('Content-Length')}
 except Exception as e: return {'name':name,'host':url.split('/')[2],'error':type(e).__name__+': '+str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool: results=list(pool.map(check,urls))
print(json.dumps({'recipient':'researcher using the public URLs recorded in input/sources.json','routes_tested':len(results),'results':results},indent=2))
PY
"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_JUDGE_OUTPUT/access_probe.py" > "$STAMPED_JUDGE_OUTPUT/access-probe.stdout" 2> "$STAMPED_JUDGE_OUTPUT/access-probe.stderr"; cat "$STAMPED_JUDGE_OUTPUT/access-probe.stdout"","yield_time_ms":30000,"max_output_tokens":1800});
text(r.output);

